62			if string(before) != string(after) {
63				t.Fatalf("time %d: Open modified the rejected file", bad)
64			}
65		}
66	}
67	
68	// 末帧从未受到校正时，保存的段结果必须与该帧保存的位姿一致：篡改位置、
69	// 朝向或方差任一项，即使文件格式与校验和都通过，也按损坏拒绝。
70	func TestOpenRejectsSegmentEndPoseMismatch(t *testing.T) {
71		tamper := []struct {
72			name string
73			edit func(p *Pose)
74		}{
75			{"x", func(p *Pose) { p.X = 3.5 }},
76			{"y", func(p *Pose) { p.Y = 0.5 }},
77			{"heading", func(p *Pose) { p.Heading = 0.5 }},
78			{"variance", func(p *Pose) { p.Variance = 1.6 }},
79		}
80		for _, tc := range tamper {
81			t.Run(tc.name, func(t *testing.T) {
82				path := filepath.Join(t.TempDir(), "m.pose")
83				buildSegmentMap(t, path)
84				fd := readFileData(t, path)
85				tc.edit(&fd.Segments[0].Result.EndPose)
86				writeFileDataRaw(t, path, &fd)
87	
88				m, err := Open(path)
89				if !errors.Is(err, ErrCorrupt) || m != nil {
90					t.Fatalf("err = %v, map = %v, want ErrCorrupt and nil map", err, m)
91				}
92				if !strings.Contains(err.Error(), "s1") || !strings.Contains(err.Error(), "300") {
93					t.Fatalf("error should name the segment and the end pose time: %v", err)
94				}
95			})
96		}
97	}
98	
99	// 合法文件正常打开：重复导入仍返回首次结果，当前位姿与历史查询不受影响。
100	func TestOpenAcceptsValidSegmentResult(t *testing.T) {
101		path := filepath.Join(t.TempDir(), "m.pose")
102		buildSegmentMap(t, path)
103	
104		m, err := Open(path)
105		if err != nil {
106			t.Fatalf("open: %v", err)
107		}
108		defer m.Close()
109		res, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
110			{Time: 100, DX: 1, MoveVariance: 0.5},
111			{Time: 200, DX: 1, MoveVariance: 0.5},
112			{Time: 300, DX: 1, MoveVariance: 0.5},
113		}})
114		if err != nil {
115			t.Fatalf("duplicate import: %v", err)
116		}
117		if res.EndPose.Time != 300 || res.EndPose.X != 3 || res.EndPose.Variance != 1.5 {
118			t.Fatalf("duplicate import result = %+v", res.EndPose)
119		}
120	}
121	
122	// 末帧已经受过校正的段，保存的结果必须等于该帧首次受到校正前的位姿，而
123	// 不是校正后的当前值：把段结果篡改为校正后的当前末位姿（与当前轨迹一致）
124	// 同样按损坏拒绝。合法文件打开后，重复导入返回首次结果，当前位姿继续返
125	// 回校正结果，两者允许不同。
126	func TestOpenSegmentResultAfterCorrection(t *testing.T) {
127		path := filepath.Join(t.TempDir(), "m.pose")
128		buildSegmentMap(t, path)
129		m, err := Open(path)
130		if err != nil {
131			t.Fatal(err)
132		}
133		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 5, Heading: 0.5, Variance: 1}}); err != nil {
134			t.Fatal(err)
135		}
136		if err := m.Close(); err != nil {
137			t.Fatal(err)
138		}
139	
140		// 未篡改：打开成功，重复导入返回首次结果，当前位姿是校正后的值。
141		m2, err := Open(path)
142		if err != nil {
143			t.Fatalf("open corrected map: %v", err)
144		}
145		res, err := m2.ImportSegment(Segment{ID: "s1", Frames: []Frame{
146			{Time: 100, DX: 1, MoveVariance: 0.5},
147			{Time: 200, DX: 1, MoveVariance: 0.5},
148			{Time: 300, DX: 1, MoveVariance: 0.5},
149		}})
150		if err != nil {
151			t.Fatalf("duplicate import after reopen: %v", err)
152		}
153		if res.EndPose.X != 3 || res.EndPose.Y != 0 || res.EndPose.Heading != 0 || res.EndPose.Variance != 1.5 {
154			t.Fatalf("duplicate import result = %+v, want first-import pose", res.EndPose)
155		}
156		cur, err := m2.CurrentPose()
157		if err != nil {
158			t.Fatal(err)
159		}
160		if cur.X == 3 && cur.Y == 0 {
161			t.Fatalf("current pose should reflect the correction: %+v", cur)
162		}
163		m2.Close()
164	
165		// 篡改：把保存的段结果换成校正后的当前末位姿——与当前轨迹一致，但
166		// 不是首次导入结果，必须按损坏拒绝。
167		fd := readFileData(t, path)
168		fd.Segments[0].Result.EndPose = fd.Trajectory[3]
169		writeFileDataRaw(t, path, &fd)
170		if m, err := Open(path); !errors.Is(err, ErrCorrupt) || m != nil {
171			t.Fatalf("replaced with corrected pose: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
172		}
173	}
174	
175	// 只有方差被校正、位置朝向保持不变时，保存的段结果仍必须携带原始方差：
176	// 篡改为目标方差（与当前轨迹一致）按损坏拒绝。
177	func TestOpenSegmentResultVarianceOnlyCorrection(t *testing.T) {
178		path := filepath.Join(t.TempDir(), "m.pose")
179		buildSegmentMap(t, path)
180		m, err := Open(path)
181		if err != nil {
182			t.Fatal(err)
183		}
184		// 恒等校正：目标位置/朝向与锚点当前值相同，只把方差改为 7。
185		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 1, Y: 0, Heading: 0, Variance: 7}}); err != nil {
186			t.Fatal(err)
187		}
188		if err := m.Close(); err != nil {
189			t.Fatal(err)
190		}
191	
192		m2, err := Open(path)
193		if err != nil {
194			t.Fatalf("open variance-only corrected map: %v", err)
195		}
196		res, err := m2.ImportSegment(Segment{ID: "s1", Frames: []Frame{
197			{Time: 100, DX: 1, MoveVariance: 0.5},
198			{Time: 200, DX: 1, MoveVariance: 0.5},
199			{Time: 300, DX: 1, MoveVariance: 0.5},
200		}})
201		if err != nil {
202			t.Fatalf("duplicate import after reopen: %v", err)
203		}
204		if res.EndPose.Variance != 1.5 {
205			t.Fatalf("duplicate import variance = %v, want original 1.5", res.EndPose.Variance)
206		}
207		if cur, _ := m2.CurrentPose(); cur.Variance != 8 {
208			t.Fatalf("current variance = %v, want corrected 8", cur.Variance)
209		}
210		m2.Close()
211	
212		// 篡改：把段结果方差改成校正后的当前方差 8（目标方差 7 加锚点之后
213		// 运动方差 1），位置朝向不动——仍不是首次导入结果。
214		fd := readFileData(t, path)
215		if fd.Trajectory[3].Variance != 8 {
216			t.Fatalf("setup: current end variance = %v, want 8", fd.Trajectory[3].Variance)
217		}
218		fd.Segments[0].Result.EndPose.Variance = 8
219		writeFileDataRaw(t, path, &fd)
220		if m, err := Open(path); !errors.Is(err, ErrCorrupt) || m != nil {
221			t.Fatalf("target variance in segment result: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
222		}
223	}
224	
225	// 对相同帧多次校正时，段结果对应的是首次校正前的位姿，不是任意一次校正
226	// 后的值：篡改为第二次校正前的中间值（即第一次校正后的值）同样拒绝。
227	func TestOpenSegmentResultWithRepeatedCorrections(t *testing.T) {
228		path := filepath.Join(t.TempDir(), "m.pose")
229		buildSegmentMap(t, path)
230		m, err := Open(path)
231		if err != nil {
232			t.Fatal(err)
233		}
234		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 0, Heading: 0, Variance: 1}}); err != nil {
235			t.Fatal(err)
236		}
237		if _, err := m.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: 20, Y: 0, Heading: 0, Variance: 2}}); err != nil {
238			t.Fatal(err)
239		}
240		if err := m.Close(); err != nil {
241			t.Fatal(err)
242		}
243	
244		m2, err := Open(path)
245		if err != nil {
246			t.Fatalf("open repeatedly corrected map: %v", err)
247		}
248		m2.Close()
249	
250		// 第一次校正后末帧位于 X=12，第二次校正后位于 X=22；首次导入值为
251		// X=3。篡改为任一校正后的值都按损坏拒绝。
252		for _, bad := range []float64{12, 22} {
253			p := filepath.Join(t.TempDir(), "m.pose")
254			buildSegmentMap(t, p)
255			mm, err := Open(p)
256			if err != nil {
257				t.Fatal(err)
258			}
259			if _, err := mm.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 0, Heading: 0, Variance: 1}}); err != nil {
260				t.Fatal(err)
261			}
262			if _, err := mm.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: 20, Y: 0, Heading: 0, Variance: 2}}); err != nil {
263				t.Fatal(err)
264			}
265			if err := mm.Close(); err != nil {
266				t.Fatal(err)
267			}
268			fd := readFileData(t, p)
269			fd.Segments[0].Result.EndPose.X = bad
270			writeFileDataRaw(t, p, &fd)
271			if m, err := Open(p); !errors.Is(err, ErrCorrupt) || m != nil {
272				t.Fatalf("end x %v: err = %v, map = %v, want ErrCorrupt and nil map", bad, err, m)
273			}
274		}
275	}
276	
277	// 校正范围只覆盖旧段的一部分、或校正之后继续导入新段，都不改写旧段的首
278	// 次结果；范围没有包含该末帧的校正也不改变它对应的值。
279	func TestOpenSegmentResultPartialAndLaterSegments(t *testing.T) {
280		path := filepath.Join(t.TempDir(), "m.pose")
281		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
282		m, err := Create(path, cfg)
283		if err != nil {
284			t.Fatal(err)
285		}
286		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
287			{Time: 100, DX: 1},
288			{Time: 200, DX: 1},
289		}}); err != nil {
290			t.Fatal(err)
291		}
292		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
293			{Time: 300, DX: 1},
294			{Time: 400, DX: 1},
295		}}); err != nil {
296			t.Fatal(err)
297		}
298		// 只覆盖 s2 的校正：s1 的末帧 200 不在范围内，s1 的首次结果不变。
299		if _, err := m.Correct(Correction{ID: "c1", Anchor: 300, Target: CorrectionTarget{X: 30, Y: 0, Heading: 0, Variance: 0}}); err != nil {
300			t.Fatal(err)
301		}
302		// 校正之后继续导入新段 s3：其首次结果记录的是校正后轨迹上的位姿。
303		if _, err := m.ImportSegment(Segment{ID: "s3", Frames: []Frame{
304			{Time: 500, DX: 1},
305		}}); err != nil {
306			t.Fatal(err)
307		}
308		if err := m.Close(); err != nil {
309			t.Fatal(err)
310		}
311	
312		m2, err := Open(path)
313		if err != nil {
314			t.Fatalf("open: %v", err)
315		}
316		defer m2.Close()
317		r1, err := m2.ImportSegment(Segment{ID: "s1", Frames: []Frame{{Time: 100, DX: 1}, {Time: 200, DX: 1}}})
318		if err != nil {
319			t.Fatal(err)
320		}
321		if r1.EndPose.X != 2 || r1.EndPose.Time != 200 {
322			t.Fatalf("s1 first result = %+v, want X=2 at t=200", r1.EndPose)
323		}
324		r2, err := m2.ImportSegment(Segment{ID: "s2", Frames: []Frame{{Time: 300, DX: 1}, {Time: 400, DX: 1}}})
325		if err != nil {
326			t.Fatal(err)
327		}
328		if r2.EndPose.X != 4 || r2.EndPose.Time != 400 {
329			t.Fatalf("s2 first result = %+v, want X=4 at t=400", r2.EndPose)
330		}
331		r3, err := m2.ImportSegment(Segment{ID: "s3", Frames: []Frame{{Time: 500, DX: 1}}})
332		if err != nil {
333			t.Fatal(err)
334		}
335		// s3 在校正之后导入：末帧从未被校正，结果与保存的该帧位姿一致。
336		if r3.EndPose.X != 32 || r3.EndPose.Time != 500 {
337			t.Fatalf("s3 first result = %+v, want X=32 at t=500", r3.EndPose)
338		}
339	}
340	
341	// 缺少逐帧依据的旧轨迹范围保留原有打开方式：旧文件中段结果的数值不被
342	// 推测核对，但末位姿时间仍须对应真实导入帧。
343	func TestOpenLegacySegmentResultNotInvented(t *testing.T) {
344		path := filepath.Join(t.TempDir(), "m.pose")
345		buildSegmentMap(t, path)
346		m, err := Open(path)
347		if err != nil {
348			t.Fatal(err)
349		}
350		writeLegacyV1File(t, path, m.state)
351		m.Close()
352	
353		// 旧文件中段结果数值与轨迹不符：缺少逐帧依据，保留既有打开规则。
354		fd := readFileData(t, path)
355		if len(fd.Sources) != 0 {
356			t.Fatalf("setup: legacy file should have no sources")
357		}
358		fd.Segments[0].Result.EndPose.X = 99
359		writeFileDataRaw(t, path, &fd)
360		m2, err := Open(path)
361		if err != nil {
362			t.Fatalf("legacy open: %v", err)
363		}
364		m2.Close()
365	
366		// 但末位姿时间不对应真实导入帧时，即使旧文件也按损坏拒绝。
367		fd = readFileData(t, path)
368		fd.Segments[0].Result.EndPose.Time = 250
369		writeFileDataRaw(t, path, &fd)
370		if m, err := Open(path); !errors.Is(err, ErrCorrupt) || m != nil {
371			t.Fatalf("legacy bad end time: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
372		}
373	}
374	
375	// 旧地图上新追加且依据完整的段仍适用本次检查：篡改新段的首次结果按损坏
376	// 拒绝，而旧段的数值仍不被推测核对。
377	func TestOpenMixedLegacyNewSegmentChecked(t *testing.T) {
378		path := filepath.Join(t.TempDir(), "m.pose")
379		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
380		m, err := Create(path, cfg)
381		if err != nil {
382			t.Fatal(err)
383		}
384		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
385			{Time: 100, DX: 1},
386			{Time: 200, DX: 1},
387		}}); err != nil {
388			t.Fatal(err)
389		}
390		writeLegacyV1File(t, path, m.state)
391		m.Close()
392	
393		m2, err := Open(path)
394		if err != nil {
395			t.Fatalf("open legacy: %v", err)
396		}
397		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
398			{Time: 300, DX: 1},
399		}}); err != nil {
400			t.Fatal(err)
401		}
402		if err := m2.Close(); err != nil {
403			t.Fatal(err)
404		}
405	
406		// 篡改新追加段的首次结果：依据完整，必须按损坏拒绝。
407		fd := readFileData(t, path)
408		if len(fd.Segments) != 2 {
409			t.Fatalf("setup: segments = %+v", fd.Segments)
410		}
411		idx := 0
412		if fd.Segments[1].ID == "new" {
413			idx = 1
414		}
415		if fd.Segments[idx].ID != "new" {
416			t.Fatalf("setup: segments = %+v", fd.Segments)
417		}
418		fd.Segments[idx].Result.EndPose.X = 3.5
419		writeFileDataRaw(t, path, &fd)
420		if m, err := Open(path); !errors.Is(err, ErrCorrupt) || m != nil {
421			t.Fatalf("tampered new segment: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
422		}
423	
424		// 篡改旧段的数值（同时把新段恢复为正确值）：旧帧缺少逐帧依据，保
425		// 持既有打开规则。
426		fd = readFileData(t, path)
427		oldIdx := 1 - idx
428		fd.Segments[idx].Result.EndPose.X = 3
429		fd.Segments[oldIdx].Result.EndPose.X = 77
430		writeFileDataRaw(t, path, &fd)
431		m3, err := Open(path)
432		if err != nil {
433			t.Fatalf("legacy segment value should not be invented: %v", err)
434		}
435		m3.Close()
436	}
