143		writeFileDataRaw(t, path, &fd)
144	
145		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
146			t.Fatalf("replayed conflict: err = %v, want ErrCorrupt, map=%v", err, m)
147		}
148	}
149	
150	// 同帧对同一标识的多条观测按保存的输入次序逐条重放：正常文件（最终均值
151	// 由次序决定的增量合并产生）必须打开成功，位置与查询结果逐位一致。
152	func TestOpenPositionReplayHonorsSameFrameOrder(t *testing.T) {
153		path := filepath.Join(t.TempDir(), "m.pose")
154		m, err := Create(path, sameFrameConfig())
155		if err != nil {
156			t.Fatal(err)
157		}
158		if _, err := m.ImportSegment(sameFrameLGeometry(true)); err != nil {
159			t.Fatal(err)
160		}
161		// 再做一次平移校正，使保存位置来自校正后重放；打开时必须按当前轨迹
162		// 与同帧次序复现出完全相同的均值 (-0.6,0)。
163		if _, err := m.Correct(Correction{
164			ID: "c-order", Anchor: 100,
165			Target: CorrectionTarget{X: -0.5, Y: 0, Heading: 0, Variance: 0},
166		}); err != nil {
167			t.Fatal(err)
168		}
169		if err := m.Close(); err != nil {
170			t.Fatal(err)
171		}
172	
173		m2, err := Open(path)
174		if err != nil {
175			t.Fatalf("open: %v", err)
176		}
177		defer m2.Close()
178		lms, err := m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
179		if err != nil {
180			t.Fatal(err)
181		}
182		if len(lms) != 1 || lms[0].Count != 5 || lms[0].X != -0.6 || lms[0].Y != 0 {
183			t.Fatalf("landmark = %+v, want (-0.6,0) count 5", lms)
184		}
185	
186		// 把同帧观测次序打乱后（观测集合与次数不变），按保存的同帧次序重放
187		// 不再复现保存值：该次序下第二条观测重放即超出合并距离，按损坏拒绝。
188		fd := readFileData(t, path)
189		obs := fd.Sources[1].Observations // t=100 帧的四条 L 观测
190		if len(obs) != 4 {
191			t.Fatalf("test setup wrong: %+v", obs)
192		}
193		obs[0].X, obs[3].X = obs[3].X, obs[0].X
194		writeFileDataRaw(t, path, &fd)
195		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
196			t.Fatalf("reordered same-frame observations: err = %v, want ErrCorrupt, map=%v", err, m)
197		}
198	}
