200	// 正常回环校正后保存的文件可以打开：核对的是当前轨迹重放出的位置，不
201	// 要求当前路标等于旧校正记录快照，也不改写那些历史快照。
202	func TestOpenPositionAcceptedAfterCorrection(t *testing.T) {
203		path := filepath.Join(t.TempDir(), "m.pose")
204		buildCorrectedMap(t, path)
205		m, err := Open(path)
206		if err != nil {
207			t.Fatalf("open corrected map: %v", err)
208		}
209		recs, _ := m.Corrections()
210		if len(recs) != 1 {
211			t.Fatalf("records = %+v", recs)
212		}
213		if err := m.Close(); err != nil {
214			t.Fatal(err)
215		}
216	
217		// 对同一范围再做一次不同校正后重开：旧记录快照保留提交时值，位置核对
218		// 只认当前轨迹。
219		m2, err := Open(path)
220		if err != nil {
221			t.Fatal(err)
222		}
223		if _, err := m2.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: -3, Y: 2, Heading: 0.5, Variance: 4}}); err != nil {
224			t.Fatal(err)
225		}
226		if err := m2.Close(); err != nil {
227			t.Fatal(err)
228		}
229		m3, err := Open(path)
230		if err != nil {
231			t.Fatalf("reopen after recorrection: %v", err)
232		}
233		defer m3.Close()
234		recs2, _ := m3.Corrections()
235		if len(recs2) != 2 || recs2[0].ID != "c1" || recs2[1].ID != "c2" {
236			t.Fatalf("records = %+v", recs2)
237		}
238	}
239	
240	// 旧地图追加有完整依据的新帧后：旧观测贡献按其原有次数与平均位置作为
241	// 固定起点参与，新观测共同决定最终位置，合法文件打开成功。
242	func TestOpenMixedLegacyPositionAccepted(t *testing.T) {
243		path := filepath.Join(t.TempDir(), "m.pose")
244		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
245		m, err := Create(path, cfg)
246		if err != nil {
247			t.Fatal(err)
248		}
249		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
250			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
251			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
252		}}); err != nil {
253			t.Fatal(err)
254		}
255		writeLegacyV1File(t, path, m.state)
256		m.Close()
257	
258		m2, err := Open(path)
259		if err != nil {
260			t.Fatal(err)
261		}
262		// 旧贡献 2 次均值 (1.5,0)；新观测 (2.5,0)，最终位置 1.5+1/3。
263		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
264			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
265		}}); err != nil {
266			t.Fatal(err)
267		}
268		if err := m2.Close(); err != nil {
269			t.Fatal(err)
270		}
271		m3, err := Open(path)
272		if err != nil {
273			t.Fatalf("reopen mixed legacy/new file: %v", err)
274		}
275		lms, _ := m3.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
276		if len(lms) != 1 || lms[0].Count != 3 {
277			t.Fatalf("landmark = %+v, want K count 3", lms)
278		}
279		approxEq(t, "mixed legacy position", lms[0].X, 1.5+1.0/3.0)
280		m3.Close()
281	
282		// 最终位置被篡改：旧贡献起点不变、来源观测不变，仍必须拒绝。
283		fd := readFileData(t, path)
284		fd.Landmarks[0].Occurrences[0].X = 8
285		writeFileDataRaw(t, path, &fd)
286		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
287			t.Fatalf("tampered mixed position: err = %v, want ErrCorrupt, map=%v", err, m)
288		}
289	
290		// 旧贡献均值被篡改（不能当成零、也不能按缺少依据的帧数代替）：拒绝。
291		fd = readFileData(t, path)
292		fd.Landmarks[0].Occurrences[0].LegacyMX = 0
293		writeFileDataRaw(t, path, &fd)
294		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
295			t.Fatalf("tampered legacy mean: err = %v, want ErrCorrupt, map=%v", err, m)
296		}
297	}
298	
299	// 完全没有逐帧观测依据的纯旧文件不核对位置：篡改保存位置后仍按现有规则
300	// 打开，不要求补造观测。
301	func TestOpenPureLegacyFileSkipsPositionCheck(t *testing.T) {
302		path := filepath.Join(t.TempDir(), "m.pose")
303		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
304		m, err := Create(path, cfg)
305		if err != nil {
306			t.Fatal(err)
307		}
308		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
309			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
310			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
311		}}); err != nil {
312			t.Fatal(err)
313		}
314		writeLegacyV1File(t, path, m.state)
315		m.Close()
316	
317		fd := readFileData(t, path)
318		if len(fd.Sources) != 0 {
319			t.Fatalf("test setup wrong: sources = %+v", fd.Sources)
320		}
321		fd.Landmarks[0].X = 42
322		writeFileDataRaw(t, path, &fd)
323		m2, err := Open(path)
324		if err != nil {
325			t.Fatalf("pure legacy file must still open: %v", err)
326		}
327		m2.Close()
328	}
329	
330	// 现有可接受的有限大坐标不能仅因新增位置检查被误报为损坏：大坐标下增量
331	// 合并保存的位置必须能由同一序列逐位重放出来。
332	func TestOpenPositionCheckAcceptsLargeFiniteCoordinates(t *testing.T) {
333		path := filepath.Join(t.TempDir(), "map.bin")
334		m, err := Create(path, Config{
335			InitialTime: 1000, MaxInterval: 100, MergeDistance: 3e307,
336		})
337		if err != nil {
338			t.Fatal(err)
339		}
340		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
341			{Time: 1001, Observations: []Observation{{ID: "L", X: 8e307, Y: 0}}},
342			{Time: 1002, Observations: []Observation{{ID: "L", X: 8e307, Y: 0}}},
343			{Time: 1003, Observations: []Observation{{ID: "L", X: 1e308, Y: 0}}},
344		}}); err != nil {
345			t.Fatal(err)
346		}
347		if _, err := m.Correct(Correction{
348			ID: "c1", Anchor: 1001,
349			Target: CorrectionTarget{X: 1e307, Y: 0, Heading: 0, Variance: 0},
350		}); err != nil {
351			t.Fatal(err)
352		}
353		if err := m.Close(); err != nil {
354			t.Fatal(err)
355		}
356		m2, err := Open(path)
357		if err != nil {
358			t.Fatalf("reopen huge-coordinate corrected map: %v", err)
359		}
360		defer m2.Close()
361		lms, _ := m2.LandmarksInRect(Rect{MinX: -math.MaxFloat64, MinY: -math.MaxFloat64, MaxX: math.MaxFloat64, MaxY: math.MaxFloat64})
362		if len(lms) != 1 || !isFinite(lms[0].X) {
363			t.Fatalf("landmark = %+v", lms)
364		}
365		want := 9e307 + (1.1e308-9e307)/3
366		if math.Abs(lms[0].X-want) > math.Abs(want)*1e-12 {
367			t.Fatalf("X = %v, want ~%v", lms[0].X, want)
368		}
369	}
